#import <AppKit/AppKit.h>
#include "putty.h"
#include "storage.h"
#include "language.h"
#include "cli-language.h"
static NSString *L(NSString *a,NSString *b){return kr_mac_language()?b:a;}
void kr_mac_show_ca(void){
    NSAlert *dialog=[NSAlert new];dialog.messageText=L(@"SSH certification authorities",@"Центры сертификации SSH");NSView *panel=[[NSView alloc]initWithFrame:NSMakeRect(0,0,650,40)];NSPopUpButton *records=[[NSPopUpButton alloc]initWithFrame:NSMakeRect(0,6,650,28) pullsDown:NO];[records addItemWithTitle:L(@"New authority",@"Новый центр сертификации")];host_ca_enum *e=enum_host_ca_start();strbuf *name=strbuf_new();while(enum_host_ca_next(e,name)){[records addItemWithTitle:[NSString stringWithUTF8String:name->s]];strbuf_clear(name);}strbuf_free(name);enum_host_ca_finish(e);[panel addSubview:records];dialog.accessoryView=panel;[dialog addButtonWithTitle:L(@"Open / New",@"Открыть / Создать")];[dialog addButtonWithTitle:L(@"Cancel",@"Отмена")];if([dialog runModal]!=NSAlertFirstButtonReturn)return;
    host_ca *ca=records.indexOfSelectedItem?host_ca_load(records.titleOfSelectedItem.UTF8String):host_ca_new();if(!ca)return;
    NSAlert *editor=[NSAlert new];editor.messageText=L(@"SSH CA",@"Центр сертификации SSH");NSView *view=[[NSView alloc]initWithFrame:NSMakeRect(0,0,650,245)];NSArray *labels=@[L(@"Name",@"Имя"),L(@"Public key (OpenSSH or base64)",@"Публичный ключ (OpenSSH или base64)"),L(@"Host matching expression",@"Выражение выбора серверов")];NSMutableArray *fields=[NSMutableArray new];strbuf *encoded=ca->ca_public_key?base64_encode_sb(ptrlen_from_strbuf(ca->ca_public_key),0):strbuf_new();NSArray *values=@[ca->name?[NSString stringWithUTF8String:ca->name]:@"",[NSString stringWithUTF8String:encoded->s],ca->validity_expression?[NSString stringWithUTF8String:ca->validity_expression]:@""];strbuf_free(encoded);for(int i=0;i<3;i++){NSTextField *label=[NSTextField labelWithString:labels[i]];label.frame=NSMakeRect(0,215-i*65,650,22);[view addSubview:label];NSTextField *field=[[NSTextField alloc]initWithFrame:NSMakeRect(0,183-i*65,650,28)];field.stringValue=values[i];[view addSubview:field];[fields addObject:field];}NSButton *sha1=[NSButton checkboxWithTitle:L(@"Allow legacy RSA/SHA-1 signatures",@"Разрешать устаревшие подписи RSA/SHA-1") target:nil action:nil];sha1.frame=NSMakeRect(0,8,290,25);sha1.state=ca->opts.permit_rsa_sha1;[view addSubview:sha1];NSButton *sha256=[NSButton checkboxWithTitle:@"RSA/SHA-256" target:nil action:nil];sha256.frame=NSMakeRect(300,8,170,25);sha256.state=ca->opts.permit_rsa_sha256;[view addSubview:sha256];NSButton *sha512=[NSButton checkboxWithTitle:@"RSA/SHA-512" target:nil action:nil];sha512.frame=NSMakeRect(475,8,170,25);sha512.state=ca->opts.permit_rsa_sha512;[view addSubview:sha512];editor.accessoryView=view;[editor addButtonWithTitle:L(@"Save",@"Сохранить")];[editor addButtonWithTitle:L(@"Cancel",@"Отмена")];if(records.indexOfSelectedItem)[editor addButtonWithTitle:L(@"Delete",@"Удалить")];NSInteger response=[editor runModal];char *failure=NULL;
    if(response==NSAlertFirstButtonReturn){sfree(ca->name);ca->name=dupstr([fields[0]stringValue].UTF8String);NSString *text=[fields[1]stringValue];NSArray *parts=[text componentsSeparatedByCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];NSMutableArray *tokens=[NSMutableArray new];for(NSString *token in parts)if(token.length)[tokens addObject:token];NSString *key=tokens.count>=2&&([tokens[0]hasPrefix:@"ssh-"]||[tokens[0]hasPrefix:@"ecdsa-"])?tokens[1]:tokens.count?tokens[0]:@"";if(!base64_valid(ptrlen_from_asciz(key.UTF8String)))failure=dupstr("Invalid SSH CA public key");else{if(ca->ca_public_key)strbuf_free(ca->ca_public_key);ca->ca_public_key=base64_decode_sb(ptrlen_from_asciz(key.UTF8String));sfree(ca->validity_expression);ca->validity_expression=dupstr([fields[2]stringValue].UTF8String);ca->opts.permit_rsa_sha1=sha1.state==NSControlStateValueOn;ca->opts.permit_rsa_sha256=sha256.state==NSControlStateValueOn;ca->opts.permit_rsa_sha512=sha512.state==NSControlStateValueOn;failure=host_ca_save(ca);}}
    else if(response==NSAlertThirdButtonReturn){NSAlert *confirm=[NSAlert new];confirm.messageText=L(@"Delete this SSH CA?",@"Удалить этот центр сертификации SSH?");[confirm addButtonWithTitle:L(@"Cancel",@"Отмена")];[confirm addButtonWithTitle:L(@"Delete",@"Удалить")];if([confirm runModal]==NSAlertSecondButtonReturn)failure=host_ca_delete(ca->name);}
    if(failure){NSAlert *error=[NSAlert new];error.messageText=@"KiTTY-NG";error.informativeText=[NSString stringWithUTF8String:kr_mac_translate(failure)];[error runModal];sfree(failure);}host_ca_free(ca);
}
